    {
        "id": "jiao-ran-98",
        "title": "酬秦山人赠别二首",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷56》",
        "verse": [
            "知君高隐占贤星，卷叶时时注佛经。姓被名公题旧里，",
            "诗将丽句号新亭。来观新月依清室，欲漱香泉护触瓶。",
            "我有主人江太守，如何相伴住禅灵。",
            "谁知卧病不妨禅，迹寄诗流性似偏。叶示黄金童子爱，",
            "书题青字古人传。时高独鹤来云外，每羡闲花在眼前。",
            "对此留君还欲别，应思石de访春泉。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
