    # ---------- 153. 早春书怀寄李少府仲宣 ----------
    {
        "id": "jiao-ran-153",
        "title": "早春书怀寄李少府仲宣",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷46》",
        "verse": [
            "早年初问法，因悟目中花。忽值胡雏起，芟夷若乱麻。",
            "脱身投彼岸，吊影念生涯。迹与空门合，心将世路赊。",
            "东田已芜没，南涧益伤嗟。崇替惊人事，凋残感物华。",
            "知君过我里，惆怅旧烟霞。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
