    # ---------- 158. 述祖德赠湖上诸沈 ----------
    {
        "id": "jiao-ran-158",
        "title": "述祖德赠湖上诸沈",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷51》",
        "verse": [
            "我祖文章有盛名，千年海内重嘉声。雪飞梁苑操奇赋，",
            "春发池塘得佳句。世业相承及我身，风流自谓过时人。",
            "初看甲乙矜言语，对客偏能鸲鹆舞。饱用黄金无所求，",
            "长裾曳地干王侯。一朝金尽长裾裂，吾道不行计亦拙。",
            "岁晚高歌悲苦寒，空堂危坐百忧攒。昔时轩盖金陵下，",
            "何处不传沈与谢。绵绵芳籍至今闻，眷眷通宗有数君。",
            "谁见予心独飘泊，依山寄水似浮云。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
