    # ---------- 448. 杂寓兴 ----------
    {
        "id": "jiao-ran-448",
        "title": "杂寓兴",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷60》",
        "verse": [
            "嗟嗟号呶子，世称谪仙俦。媚俗被鲛绡，欺天荐昫修。",
            "奔景谓可致，驰龄言易流。燕昭昧往事，嬴政亡前筹。",
            "三山果不见，九仙忽悠悠。君看牛山乐，君见麋浦游。",
            "昨日千金子，联绵成古丘。吾将揽明月，照尔生死流。",
            "至乐享爰居，惭贻达者尤。冥冥光尘内，机丧成海沤。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 449. 杂兴六首 ----------
    {
        "id": "jiao-ran-449",
        "title": "杂兴六首",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷61》",
        "verse": [
            "吾观谈天客，工言丧其精。万物资广庇，此中何有情。",
            "若为昧颜跖，修短怨太清。高论让邹子，放词征屈生。",
            "请从象外推，至论尤明明。",
            "短龄役长世，扰扰悟不早。嫔女身后空，欢娱梦中好。",
            "从教西陵树，千载伤怀抱。鹤驾何冥冥，鳌洲去浩浩。",
            "柔颜感三花，凋发悲蔓草。月中伐桂人是谁，",
            "翻使年年不衰老。",
            "谁高齐公子，泣听雍门琴。死且何足伤，殊非达人心。",
            "独高庭中鹤，意远贵氛埃。有时青冥游，顾我还下来。",
            "白云琅玕色，一片生虚无。此物若无心，若何卷还舒。",
            "疏散遂吾性，栖山更无机。寥寥高松下，独有闲云归。",
            "精意不可道，冥然还掩扉。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 450. 偶然五首 ----------
    {
        "id": "jiao-ran-450",
        "title": "偶然五首",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷62》",
        "verse": [
            "乐禅心似荡，吾道不相妨。独悟歌还笑，谁言老更狂。",
            "偶然寂无喧，吾了心性源。可嫌虫食木，不笑鸟能言。",
            "隐心不隐迹，却欲住人寰。欠树移春树，无山看画山。",
            "居喧我未错，真意在其间。",
            "虏语嫌不学，胡音从不翻。说禅颠倒是，乐杀金王孙。",
            "真隐须无矫，忘名要似愚。只将两条事，空却汉潜夫。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
