    # ---------- 500. 湖南草堂读书招李少府 ----------
    {
        "id": "jiao-ran-500",
        "title": "湖南草堂读书招李少府",
        "author": "皎然",
        "poet_id": "jiao-ran",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷41》",
        "verse": [
            "削去僧家事，南池便隐居。为怜松子寿，还卜道家书。",
            "药院常无客，茶樽独对余。有时招逸史，来饭野中蔬。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
